DO $$DECLARE t uuid;BEGIN FOR t IN SELECT id FROM sys_tenant LOOP PERFORM set_config('crm.tenant_id',t::text,true);UPDATE sys_role_policy SET knowledge_can_read=can_read,knowledge_can_write=can_write,knowledge_can_publish=can_write AND role_code='SALES_MANAGER',version=version+1 WHERE tenant_id=t;END LOOP;PERFORM set_config('crm.tenant_id','',true);END$$;
CREATE TABLE crm_knowledge_category(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,name varchar(100) NOT NULL,parent_id uuid,active boolean NOT NULL DEFAULT true,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,parent_id) REFERENCES crm_knowledge_category(tenant_id,id));
CREATE TABLE crm_knowledge_article(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,category_id uuid NOT NULL,title varchar(200) NOT NULL,body text NOT NULL CHECK(length(body) BETWEEN 1 AND 20000),author_member_id uuid NOT NULL,
 status varchar(20) NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','PUBLISHED','ARCHIVED')),published_version bigint,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,category_id) REFERENCES crm_knowledge_category(tenant_id,id),FOREIGN KEY(tenant_id,author_member_id) REFERENCES sys_tenant_member(tenant_id,id));
CREATE TABLE crm_knowledge_revision(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,article_id uuid NOT NULL,business_version bigint NOT NULL,action varchar(40) NOT NULL,snapshot jsonb NOT NULL,reason varchar(500) NOT NULL DEFAULT '',actor_member_id uuid NOT NULL,actor_name_snapshot varchar(100) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(tenant_id,id),UNIQUE(tenant_id,article_id,business_version),FOREIGN KEY(tenant_id,article_id) REFERENCES crm_knowledge_article(tenant_id,id),FOREIGN KEY(tenant_id,actor_member_id) REFERENCES sys_tenant_member(tenant_id,id));
CREATE TABLE crm_ticket_article(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,ticket_id uuid NOT NULL,article_id uuid NOT NULL,article_version bigint NOT NULL,actor_member_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(tenant_id,id),UNIQUE(tenant_id,ticket_id,article_id,article_version),FOREIGN KEY(tenant_id,ticket_id) REFERENCES crm_ticket(tenant_id,id),FOREIGN KEY(tenant_id,article_id,article_version) REFERENCES crm_knowledge_revision(tenant_id,article_id,business_version),FOREIGN KEY(tenant_id,actor_member_id) REFERENCES sys_tenant_member(tenant_id,id));
DO $$DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['crm_knowledge_category','crm_knowledge_article','crm_knowledge_revision','crm_ticket_article'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',n);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',n);EXECUTE format('CREATE POLICY tenant_boundary ON %I USING(tenant_id=nullif(current_setting(''crm.tenant_id'',true),'''')::uuid) WITH CHECK(tenant_id=nullif(current_setting(''crm.tenant_id'',true),'''')::uuid)',n);END LOOP;END$$;
GRANT SELECT,INSERT,UPDATE ON crm_knowledge_category,crm_knowledge_article TO crm_runtime;
GRANT SELECT,INSERT ON crm_knowledge_revision,crm_ticket_article TO crm_runtime;
